package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.Document;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Cleaner;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.safety.Cleaner.*;
import static org.junit.Assert.*;

public class Cleaner_clean_TriageGen2Test {

    @Test
    public void testClean_NullDirtyDocument_ThrowsNullPointerException() {
        Cleaner cleaner = new Cleaner(new Whitelist());
        try {
            cleaner.clean(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testClean_EmptyDirtyDocument_ReturnsEmptyDocument() {
        Document dirtyDoc = Document.createShell("");
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document cleanDoc = cleaner.clean(dirtyDoc);
        assertEquals(0, cleanDoc.body().children().size());
    }

    @Test
    public void testClean_SingleElementDirtyDocument_ReturnsSameElementInCleanDocument() {
        Document dirtyDoc = Document.createShell("<html><body>Hello</body></html>");
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document cleanDoc = cleaner.clean(dirtyDoc);
        assertEquals(1, cleanDoc.body().children().size());
        Element element = cleanDoc.body().child(0);
        assertEquals("Hello", element.text());
    }

    @Test
    public void testClean_MultipleElementsDirtyDocument_ReturnsElementsInCleanDocument() {
        Document dirtyDoc = Document.createShell("<html><body><p>Hello</p><p>World</p></body></html>");
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document cleanDoc = cleaner.clean(dirtyDoc);
        assertEquals(2, cleanDoc.body().children().size());
        Element element1 = cleanDoc.body().child(0);
        assertEquals("Hello", element1.text());
        Element element2 = cleanDoc.body().child(1);
        assertEquals("World", element2.text());
    }

    @Test
    public void testClean_DirtyDocumentWithComments_ReturnsCleanDocument() {
        Document dirtyDoc = Document.createShell("<html><body><!-- comment --><p>Hello</p><!-- another comment --></body></html>");
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document cleanDoc = cleaner.clean(dirtyDoc);
        assertEquals(1, cleanDoc.body().children().size());
        Element element = cleanDoc.body().child(0);
        assertEquals("Hello", element.text());
    }

    @Test
    public void testClean_DirtyDocumentWithScript_ReturnsCleanDocument() {
        Document dirtyDoc = Document.createShell("<html><body><script>alert('Hello')</script></body></html>");
        Cleaner cleaner = new Cleaner(new Whitelist());
        Document cleanDoc = cleaner.clean(dirtyDoc);
        assertEquals(0, cleanDoc.body().children().size());
    }
}
